// =================================================================
// JARVIS — Полная обработка входящего сообщения
// Валидация + команды + маршрутизация в одной ноде
// =================================================================

const update = $input.first().json;
const message = update.message || update;

// Достаём текст из разных возможных мест
const text = message?.text || message?.message?.text || '';

if (!text) {
  return []; // Игнорируем не-текстовые
}

const userMessage = text.trim();

// Достаём chat info из разных возможных структур
const chatId = String(
  message?.chat?.id ||
  message?.message?.chat?.id ||
  message?.from?.id ||
  message?.message?.from?.id ||
  ''
);

const userId = String(
  message?.from?.id ||
  message?.message?.from?.id ||
  ''
);

const username =
  message?.from?.username ||
  message?.from?.first_name ||
  message?.message?.from?.username ||
  message?.message?.from?.first_name ||
  'Unknown';

console.log(`JARVIS: ${username} (chat:${chatId}): ${userMessage}`);

if (!chatId) {
  console.error('No chatId found in:', JSON.stringify(message).substring(0, 500));
  return [];
}

// === /start ===
if (userMessage === '/start') {
  return [
    {
      json: {
        route: 'command',
        chatId: chatId,
        text: '\u{1F916} *JARVIS активирован*\n\n' +
          'Я ваш персональный AI-оркестратор. Просто говорите — я пойму что делать.\n\n' +
          '*Что я умею:*\n' +
          '\u{1F4A1} Принимать идеи и оценивать их\n' +
          '\u{1F4DD} Сохранять заметки и решения\n' +
          '\u{1F50D} Отвечать на вопросы из базы знаний\n' +
          '\u{1F4CB} Принимать задачи\n\n' +
          '*Команды:*\n' +
          '/status — статистика памяти\n' +
          '/ideas — список идей\n' +
          '/help — справка\n\n' +
          'Просто напишите что угодно!'
      }
    }
  ];
}

// === /help ===
if (userMessage === '/help') {
  return [
    {
      json: {
        route: 'command',
        chatId: chatId,
        text: '\u{1F4D6} *JARVIS — Справка*\n\n' +
          '*Типы сообщений (определяю автоматически):*\n' +
          '\u{1F4A1} IDEA — идеи (оцениваю feasibility/impact)\n' +
          '\u{1F4DD} NOTE — заметки и мысли\n' +
          '\u{1F50D} QUERY — вопросы (ищу в базе знаний)\n' +
          '\u{1F4CB} TASK — задачи\n\n' +
          '*Примеры:*\n' +
          '• Идея — сделать калькулятор пожарной опасности\n' +
          '• Какие требования к СОУЭ 3 типа?\n' +
          '• Запиши — нужно обновить спецификацию\n\n' +
          '*Команды:*\n' +
          '/status — статистика\n' +
          '/ideas — список идей\n' +
          '/help — эта справка'
      }
    }
  ];
}

// === /status ===
if (userMessage === '/status') {
  return [
    {
      json: {
        route: 'status',
        chatId: chatId
      }
    }
  ];
}

// === /ideas ===
if (userMessage === '/ideas') {
  return [
    {
      json: {
        route: 'ideas',
        chatId: chatId
      }
    }
  ];
}

// === Обычное сообщение — на классификацию ===
return [
  {
    json: {
      route: 'classify',
      userMessage: userMessage,
      userId: userId,
      username: username,
      chatId: chatId
    }
  }
];

// Запрос статистики из Supabase напрямую через Code ноду
const chatId = $json.chatId;

// Возвращаем chatId для следующей ноды
// Статистика будет получена через HTTP Request
return [{ json: { chatId } }];

const chatId = $('Status Prep').first().json.chatId;
const stats = $input.all().map(i => i.json);

let text = '\u{1F4CA} *JARVIS — Статистика памяти*\n\n';

if (!stats || stats.length === 0 || (stats.length === 1 && !stats[0].content_type)) {
  text += 'Память пуста. Начните общение!';
} else {
  let total = 0;
  const emojis = {
    'idea': '\u{1F4A1}', 'task': '\u{1F4CB}', 'note': '\u{1F4DD}',
    'query': '\u{1F50D}', 'decision': '\u2696\uFE0F', 'context': '\u{1F4CE}',
    'agent_report': '\u{1F916}', 'digest': '\u{1F4F0}'
  };
  stats.forEach(s => {
    if (s.content_type) {
      const emoji = emojis[s.content_type] || '\u{1F4C4}';
      text += `${emoji} ${s.content_type}: ${s.count}\n`;
      total += parseInt(s.count || 0);
    }
  });
  text += `\n*Всего записей:* ${total}`;
}

return [{ json: { chatId: chatId, text: text } }];

const chatId = $('Ideas Prep').first().json.chatId;
const ideas = $input.all().map(i => i.json);

let text = '\u{1F4A1} *JARVIS — Банк идей*\n\n';

if (!ideas || ideas.length === 0 || !ideas[0].id) {
  text += 'Пока нет идей. Расскажите мне свою идею!';
} else {
  ideas.forEach((idea, idx) => {
    const meta = idea.metadata || {};
    const f = meta.feasibility_score ? `F:${meta.feasibility_score}` : '';
    const im = meta.impact_score ? `I:${meta.impact_score}` : '';
    const scores = (f || im) ? ` [${f} ${im}]` : '';
    const date = new Date(idea.created_at).toLocaleDateString('ru-RU');
    const summary = idea.summary || (idea.content || '').substring(0, 80);
    text += `${idx + 1}. ${summary}${scores}\n   _${date}_\n\n`;
  });
}

return [{ json: { chatId: chatId, text: text } }];

// =================================================================
// JARVIS — Парсинг классификации + подготовка сохранения
// =================================================================

const claudeText = $json.content?.[0]?.text || '{}';
const prev = $('Router').first().json;

let cls;
try {
  cls = JSON.parse(claudeText);
} catch (e) {
  cls = { type: 'NOTE', summary: prev.userMessage.substring(0, 100), priority: 'medium', tags: ['unclassified'] };
}

const contentType = (cls.type || 'NOTE').toLowerCase();

// Эмодзи
const te = { 'IDEA': '\u{1F4A1}', 'TASK': '\u{1F4CB}', 'NOTE': '\u{1F4DD}', 'QUERY': '\u{1F50D}' };
const pe = { 'critical': '\u{1F534}', 'high': '\u{1F7E0}', 'medium': '\u{1F7E1}', 'low': '\u{1F7E2}' };

let text = `${te[cls.type] || '\u{1F4C4}'} *${cls.type}* ${pe[cls.priority] || ''} ${cls.priority}\n\n`;
text += `\u{1F4CC} ${cls.summary}\n`;
if (cls.tags && cls.tags.length) text += `\u{1F3F7} ${cls.tags.join(', ')}\n`;

if (cls.type === 'IDEA' && cls.feasibility_score) {
  text += `\n\u{1F4CA} *Оценка:*\n`;
  text += `  Реализуемость: ${cls.feasibility_score}/10\n`;
  text += `  Импакт: ${cls.impact_score}/10\n`;
  if (cls.evaluation_notes) text += `  ${cls.evaluation_notes}\n`;
}

text += `\n\u2705 Сохранено в память JARVIS`;

const metadata = {};
if (cls.feasibility_score) metadata.feasibility_score = cls.feasibility_score;
if (cls.impact_score) metadata.impact_score = cls.impact_score;
if (cls.evaluation_notes) metadata.evaluation_notes = cls.evaluation_notes;
metadata.telegram_user_id = prev.userId;
metadata.telegram_username = prev.username;

return [{
  json: {
    chatId: prev.chatId,
    text: text,
    // Для сохранения
    content: prev.userMessage,
    content_type: contentType,
    summary: cls.summary || prev.userMessage.substring(0, 100),
    tags: cls.tags || [],
    source: 'telegram',
    priority: cls.priority || 'medium',
    status: 'active',
    metadata: metadata,
    classType: cls.type
  }
}];

// Объединяем данные из Parse и Embed
const parsed = $('Parse & Prepare').first().json;
const embedding = $json.embedding;

return [{
  json: {
    ...parsed,
    embedding: embedding
  }
}];
